parts:
                   
                if txt and txt != "-":
                    cleaned = (
                        txt.replace(stockID, "")
                        .replace("(", "")
                        .replace(")", "")
                        .replace("（", "")
                        .replace("）", "")
                        .strip()
                    )
                    cleaned = normalize_space(cleaned)
                    if cleaned:
                        return cleaned
        except:
            continue

    return f"unknown_stock_{stockID}"


