def get_kline_and_ma(jiaoyisuo, stockID, max_retry=4, timeout=20):
    today_str = today_str_compact()
    secid = f"{jiaoyisuo}.{stockID}"

    api_url = (
        f"https://push2his.eastmoney.com/api/qt/stock/kline/get?"
        f"secid={secid}&ut=fa5fd1943c7b386f172d6893dbfba10b"
        f"&fields1=f1,f2,f3,f4,f5,f6"
        f"&fields2=f51,f52,f53,f54,f55,f56,f57,f58,f59,f60,f61"
        f"&klt=101&fqt=1&end={today_str}&lmt=210"
    )

    headers = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
            "(KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36"
        ),
        "Referer": "https://quote.eastmoney.com/",
        "Accept": "application/json,text/plain,*/*",
    }

    for _ in range(max_retry):
        try:
            req = Request(api_url, headers=headers)
            with urlopen(req, timeout=timeout) as resp:
                body = resp.read().decode("utf-8", errors="ignore").strip()

            if not body:
                raise Exception("K线接口返回空内容")

            data = json.loads(body)

            if "data" not in data or not data["data"] or "klines" not in data["data"]:
                raise Exception("未找到K线数据")

            klines = data["data"]["klines"]
            if len(klines) < 90:
                raise Exception(f"K线数据不足90条，当前只有 {len(klines)} 条")

            parsed = []
            for row in klines:
                arr = row.split(",")
                parsed.append({
                    "date": arr[0].replace("-", ""),
                    "open": float(arr[1]),
                    "close": float(arr[2]),
                    "high": float(arr[3]),
                    "low": float(arr[4]),
                    "volume": float(arr[5]),
                    "amount": float(arr[6]) if len(arr) > 6 and arr[6] else 0.0,
                })

            closes = [x["close"] for x in parsed]
            current_close = parsed[-1]["close"]
            prev_5th_close = parsed[-6]["close"]
            five_day_change = (current_close - prev_5th_close) / prev_5th_close

            def ma(n):
                return sum(closes[-n:]) / n

            ma_data = {
                "chg5": round(five_day_change * 100, 4),
                "MA5": round(ma(5), 4),
                "MA10": round(ma(10), 4),
                "MA20": round(ma(20), 4),
                "MA30": round(ma(30), 4),
                "MA40": round(ma(40), 4),
                "MA50": round(ma(50), 4),
                "MA60": round(ma(60), 4),
                "MA70": round(ma(70), 4),
                "MA80": round(ma(80), 4),
                "MA90": round(ma(90), 4),
            }

            lines = [
                f"5日涨幅: {five_day_change:.2%}",
                (
                    f"MA5: {ma(5):.2f}, MA10: {ma(10):.2f}, MA20: {ma(20):.2f}, "
                    f"MA30: {ma(30):.2f}, MA40: {ma(40):.2f}, MA50: {ma(50):.2f}, "
                    f"MA60: {ma(60):.2f}, MA70: {ma(70):.2f}, MA80: {ma(80):.2f}, MA90: {ma(90):.2f}"
                ),
            ]

            return True, ma_data, lines

        except:
            time.sleep(1.5)

    return False, {}, []


