def extract_close_change_from_block(block):
    lines = [x.strip() for x in block.splitlines() if x.strip()]
    if not lines:
        return None, None

    close = None
    change_pct = None
    start_idx = 0

    for i, line in enumerate(lines):
        if line.startswith("股票数据"):
            start_idx = i + 1
            break

    skip_keywords = [
        "今开", "昨收", "最高价", "最低价", "换手率", "量比", "成交量", "成交额",
        "筹码分布", "5日涨幅", "MA", "Date:", "股票数据", "未找到",
    ]

    for line in lines[start_idx:]:
        if close is None:
            if not any(k in line for k in skip_keywords):
                v = parse_float(line)
                if v is not None:
                    close = v
                    continue
        else:
            if "%" in line:
                v = parse_float(line)
                if v is not None:
                    change_pct = v
                    break

    return close, change_pct


def is_valid_log_block(block):
    close, _ = extract_close_change_from_block(block)
    if close is None:
        return False

    needed = ["MA5", "MA10", "MA20", "MA30", "MA60", "MA90"]
    for k in needed:
        if not re.search(rf"{k}[:：]?\s*[0-9.]+", block):
            return False

    return True


def today_block_status(log_path, date_str=None):
