    found_today = False
    for block in blocks:
        if f"Date: {date_str}" in block:
            found_today = True
            if is_valid_log_block(block):
                return "valid"

    return "invalid" if found_today else "none"


def remove_today_blocks(log_path, date_str=None):
    if date_str is None:
        date_str = today_str_dash()

    if not os.path.exists(log_path):
        return 0

    text = read_text(log_path)
    blocks = split_blocks(text)

    keep = []
    removed = 0
    for block in blocks:
        if f"Date: {date_str}" in block:
            removed += 1
        else:
            keep.append(block)

    if removed > 0:
        if keep:
            write_text(log_path, "\n\n".join(keep).rstrip() + "\n")
        else:
            try:
                os.remove(log_path)
            except:
                write_text(log_path, "")

    return removed


