def build_history_from_log(log_path, stock_name, stock_code):
    with open(log_path, "r", encoding="utf-8") as f:
        text = f.read()

    blocks = split_blocks(text)
    history = []

    for block in blocks:
        item = {
            "date": None,
            "name": stock_name,
            "code": stock_code,
            "close": None,
            "change_pct": None,
            "open": None,
            "prev_close": None,
            "high": None,
            "low": None,
            "turnover_rate": None,
            "volume_ratio": None,
            "volume": None,
            "amount": None,
            "profit_ratio": None,
            "avg_cost": None,
            "cost_90_low": None,
            "cost_90_high": None,
            "conc_90": None,
            "cost_70_low": None,
            "cost_70_high": None,
            "conc_70": None,
            "chg5": None,
            "MA5": None,
            "MA10": None,
            "MA20": None,
            "MA30": None,
            "MA40": None,
            "MA50": None,
            "MA60": None,
            "MA70": None,
            "MA80": None,
            "MA90": None,
        }

        m = re.search(r"Date:\s*(\d{4}-\d{2}-\d{2})", block)
        if m:
            item["date"] = m.group(1)

        close, change_pct = extract_close_change_from_block(block)
        item["close"] = close
        item["change_pct"] = change_pct

        pairs = {
            "open": r"今开[:：]?\s*([0-9.]+)",
            "prev_close": r"昨收[:：]?\s*([0-9.]+)",
            "high": r"最高价[:：]?\s*([0-9.]+)",
            "low": r"最低价[:：]?\s*([0-9.]+)",
            "turnover_rate": r"换手率[:：]?\s*([0-9.]+)%",
            "volume_ratio": r"量比[:：]?\s*([0-9.]+)",
            "volume": r"成交量[:：]?\s*([0-9.]+)万",
            "amount": r"成交额[:：]?\s*([0-9.]+)亿",
            "profit_ratio": r"获利比例[:：]?\s*([0-9.]+)%",
            "avg_cost": r"平均成本[:：]?\s*([0-9.]+)",
            "chg5": r"5日涨幅[:：]?\s*([-0-9.]+)%",
            "MA5": r"MA5[:：]?\s*([0-9.]+)",
            "MA10": r"MA10[:：]?\s*([0-9.]+)",
            "MA20": r"MA20[:：]?\s*([0-9.]+)",
            "MA30": r"MA30[:：]?\s*([0-9.]+)",
            "MA40": r"MA40[:：]?\s*([0-9.]+)",
            "MA50": r"MA50[:：]?\s*([0-9.]+)",
            "MA60": r"MA60[:：]?\s*([0-9.]+)",
            "MA70": r"MA70[:：]?\s*([0-9.]+)",
            "MA80": r"MA80[:：]?\s*([0-9.]+)",
            "MA90": r"MA90[:：]?\s*([0-9.]+)",
        }

        for k, p in pairs.items():
            m = re.search(p, block)
            if m:
                item[k] = parse_float(m.group(1))

        m = re.search(r"90%成本[:：]?\s*([0-9.]+)\s*-\s*([0-9.]+)", block)
        if m:
            item["cost_90_low"] = float(m.group(1))
            item["cost_90_high"] = float(m.group(2))

        m = re.search(r"70%成本[:：]?\s*([0-9.]+)\s*-\s*([0-9.]+)", block)
        if m:
            item["cost_70_low"] = float(m.group(1))
            item["cost_70_high"] = float(m.group(2))

        concs = list(re.finditer(r"集中度[:：]?\s*([0-9.]+)%", block))
        if len(concs) >= 1:
            item["conc_90"] = float(concs[0].group(1))
        if len(concs) >= 2:
            item["conc_70"] = float(concs[1].group(1))

        if item["date"] and item["close"] is not None:
            history.append(item)

    uniq = {}
    for row in history:
        uniq[row["date"]] = row

    result = list(uniq.values())
    result.sort(key=lambda x: x["date"])
    return result


