        return (
            "大致看 3 到 8 个交易日。"
            " 这种压缩结构本身不会拖特别久，后面就差市场给一个明确的量价态度。"
        )

    if state == 2 and sub_state == "2B-EarlyBull":
        return (
            "我更倾向于看 1 到 2 周。"
            " 因为它已经不是纯粘合了，但又还没完全进入强趋势，所以通常还需要一点时间确认到底是继续走强，还是只是试探一下。"
        )

    if state in [3, "3+"]:
        return (
            "如果没有明显破位，这种结构通常不用震太久，快一点的话 3 到 5 个交易日，慢一点也就是一周左右。"
        )

    if state == 1:
        return (
            "这种我一般按 2 到 4 周看。"
            " 因为它当前主要任务不是起飞，而是先把上方成本和中期均线慢慢修掉。"
        )

    return (
        "按现在这个状态，我还是倾向于看 1 到 3 周。"
        " 它现在更像在做换手和结构确认，真正想启动，得等均线、筹码和量能重新拧到一起。"
    )


def q5_dynamic(today, prev, history, aei_trend, aei_today, aei5sum, penetration, premium, trend):
    event_text = aei_event_summary(history, topn=2)

    if aei5sum > 4.5:
        return (
            "我的判断是：有，而且已经不算弱了。"
            f" 近阶段比较突出的AEI节点出现在 {event_text}，这说明不是单日脉冲，而是资金确实有过比较成体系的承接动作。"
            " 如果后面在缩量背景下，集中度还能继续往好的方向走，那基本可以把它理解成主力没走，还在做锁仓和收筹。"
        )

    if 2.5 <= aei5sum <= 4.5:
        return (
            "我的判断是：有低位收集迹象，但力度还没有强到特别确定。"
            f" 从AEI看，像 {event_text} 这种阶段确实出现过承接动作，说明资金不是完全没管它。"
            " 但从持续性看，它更像边洗边接，而不是已经进入特别强的控盘式吸筹。"
        )

    return (
        "我的判断是：目前还不能说主力在做特别高质量的低位收集。"
        f" AEI这边虽然也有阶段性异动，比如 {event_text}，但整体延续性还不够强。"
        " 所以更稳妥的理解还是：普通换手里夹杂着一些承接，而不是特别明确的主升前吸筹。"
    )


def q6_dynamic(today, prev, history, state, sub_state, penetration, premium, trend, aei_today, aei5sum):
    support_low, support_high, pressure_low, pressure_high = get_support_pressure(today)

    if state == 2 and sub_state == "2B-Compress":
        if penetration is not None and penetration < 15:
            return (
                "我更倾向于说：已经接近了，但还差最后一脚。"
                f" 现在穿透率大概只有 {format_num(penetration, 2)}%，说明价格还在主筹码区边缘活动，真正往上打的动作还没完全出来。"
                f" 但这种结构本身已经很像起爆前夜了，只要后面能带量越过 {format_num(today['avg_cost']) if today.get('avg_cost') is not None else format_num(pressure_low)} 附近的平均成本/关键压力区，就很容易进入启动节奏。"
            )
        return (
            "我会说：已经很接近拉升准备区了，但市场还没正式按下按钮。"
            " 结构弹性已经出来了，现在差的是一根有说服力的量价确认。"
        )

    if state in [3, "3+"] and trend:
        return (
            "从结构角度看，它已经具备拉升前提。"
            " 现在不是有没有条件的问题，而是后面量能愿不愿意继续配合。"
        )

    if trend is False:
        return (
            "我暂时不会说它已经准备拉升。"
            " 因为股价还没真正站回平均成本之上，这意味着上方筹码压力还没有完全消化完。"
            " 更准确地说，它现在还是蓄势后段，不是正式起飞前夜。"
        )

    return (
        f"我的判断是：正在准备，但还没完成。"
        f" 真正的确认点还是看它能不能有效突破 {format_num(pressure_high) if pressure_high is not None else format_num(pressure_low)} 一带，"
        "而且突破后不能马上缩回去。"
    )


