    lines.append(f"Trend：{'正向(True)' if trend else '弱势(False)'}" if trend is not None else "Trend：-")
    lines.append(f"Signal：{signal} | {desc}")
    lines.append("")
    lines.append("【关键价位分区】")
    lines.append("━━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"卖压区：{format_num(pressure_low)} – {format_num(pressure_high)}")
    lines.append(f"平衡区：{format_num(balance_low)} – {format_num(balance_high)}")
    lines.append(f"支撑区：{format_num(support_low)} – {format_num(support_high)}")
    lines.append("━━━━━━━━━━━━━━━━━━━━━━━")
    lines.append(f"当前股价：{format_num(today['close'])}")

    return "\n".join(lines), today


